// Signal descriptors, not a trained semantic sound classifier.
export function soundDescription(event){const duration=Math.max(0,event.duration);if(duration<=350&&event.rise>=14)return {title:'Богино огцом дуу',possible:'Тогшилт эсвэл алга ташилт байж болно. Яг эх үүсвэрийг тогтоогоогүй.',confidence:null};if(duration>=700&&event.tonalFrames/event.frames>.65)return {title:'Давтамж төвлөрсөн үргэлжилсэн дуу',possible:'Дохио эсвэл төхөөрөмжийн дуу байж болно. Яг эх үүсвэрийг тогтоогоогүй.',confidence:null};if(duration>=700)return {title:'Үргэлжилсэн дуу',possible:'Яриа, шуугиан эсвэл бусад дуу байж болно. Үгийг яриа таних горимоор шалгана.',confidence:null};return {title:'Тодорхойгүй дуу',possible:'Дууны өөрчлөлт бүртгэгдсэн. Эх үүсвэрийг тогтоох мэдээлэл хангалтгүй.',confidence:null}}
export class SoundEvents{
 constructor(){this.baseline=-60;this.warm=[];this.active=null;this.cooldown=0;this.started=null}
 update(db,now,tonal=false){if(!Number.isFinite(db))return null;if(this.started==null)this.started=now;if(now-this.started<1000){this.warm.push(db);this.baseline=this.warm.reduce((a,b)=>a+b,0)/this.warm.length;return null}const threshold=Math.max(-45,this.baseline+14);if(!this.active){if(db>threshold&&now>=this.cooldown)this.active={start:now,last:now,peak:db,rise:db-this.baseline,frames:1,tonalFrames:Number(tonal)};else this.baseline=this.baseline*.98+db*.02;return null}const e=this.active;e.frames++;e.tonalFrames+=Number(tonal);e.peak=Math.max(e.peak,db);if(db>threshold-5)e.last=now;if(now-e.last>=200||now-e.start>=5000){this.active=null;this.cooldown=now+350;e.duration=e.last-e.start;return {...e,...soundDescription(e)}}return null}
}
export function concentratedSpectrum(values){let sum=0,peak=0;for(const db of values){if(!Number.isFinite(db))continue;const power=10**(db/10);sum+=power;peak=Math.max(peak,power)}return sum>1e-12&&peak/sum>.45}
